ee:variables.ee:set-variable:
%dw 2.0
import dw::Crypto
import dw::core::Binaries
output application/java
var rawBin = if (vars.rawContent is Binary) (vars.rawContent as Binary)
             else if (vars.rawContent is String) (vars.rawContent as Binary)
             else (write(vars.rawContent, "application/json") as Binary)
---
Binaries::toHex(Crypto::hashWith(rawBin, "SHA-256"))

%dw 2.0
output application/json

var raw = vars.rawContent
var isXml = vars.fileFormat == "XML"

var parsed = if (raw is Binary or raw is String) (
	if (isXml) read(raw, "application/xml")
	else read(raw, "application/csv", {header: true})
) else raw

var records = if (isXml) (
	if (parsed.employeeImport != null and parsed.employeeImport.employees != null) (
		(parsed.employeeImport.employees.*employee default [])
	) else []
) else (
	(parsed default [])
)

var declared = if (isXml) (
	if (parsed.employeeImport != null and parsed.employeeImport.header != null and parsed.employeeImport.header.recordCount != null) (
		parsed.employeeImport.header.recordCount as Number default null
	) else null
) else null

var source = if (isXml) (
	if (parsed.employeeImport != null and parsed.employeeImport.header != null and parsed.employeeImport.header.sourceSystem != null) (
		parsed.employeeImport.header.sourceSystem
	) else "HRMS-XML"
) else "HRMS-CSV"

---
{
	sourceSystem: source,
	declaredCount: declared,
	records: records map ((emp, idx) -> {
		recordIndex: idx + 1,
		employeeId: trim(emp.employeeId default ""),
		firstName: trim(emp.firstName default ""),
		lastName: trim(emp.lastName default ""),
		dateOfBirth: trim(emp.dateOfBirth default ""),
		dateOfJoining: trim(emp.dateOfJoining default ""),
		officialEmail: trim(emp.officialEmail default ""),
		mobile: trim(emp.mobile default ""),
		departmentCode: trim(emp.departmentCode default ""),
		designation: trim(emp.designation default ""),
		locationCode: trim(emp.locationCode default ""),
		employmentType: trim(emp.employmentType default ""),
		managerId: trim(emp.managerId default "")
	})
}
